// Curated maps for the next library expansion. Each beat has a plot-level source
// and the links show the causal or interpretive relationships between beats.
const build = ({ id, title, summary, twistType, source, beats, links }) => {
  const nodes = [
    { id, label: title, graphLabel: title, type: 'film', spoilerLevel: 0, size: 9, revealText: `Story map: ${title}`, revealSubtext: summary, revealClassification: 'Film Hub' },
    ...beats.map(([key, label, type, spoilerLevel, stage, classification, revealText, revealSubtext], index) => ({
      id: `${id}-${key}`, label, graphLabel: label, type, spoilerLevel,
      size: type === 'twist' ? 8 : type === 'character' ? 5.5 : 4.5,
      timelineOrder: index + 1, timelineStage: stage, revealClassification: classification,
      revealText, revealSubtext, sources: [source],
    })),
  ];
  const edge = ([from, to, relationship, explanation, spoilerLevel = 1]) => ({
    source: from === 'film' ? id : `${id}-${from}`,
    target: to === 'film' ? id : `${id}-${to}`,
    film: id, relationship, explanation, spoilerLevel,
  });
  return { nodes, links: links.map(edge), twistType };
};

const b = (key, label, type, level, stage, classification, reveal, detail) => [key, label, type, level, stage, classification, reveal, detail];

